  3	public final class ArrayDisjointSet implements DisjointSet {
  4	    private static final String NEGATIVE_SIZE_MESSAGE = "size must be non-negative";
  5	
  6	    private final int[] parent;
  7	    private final int[] componentSize;
  8	    private int componentCount;
  9	
 10	    public ArrayDisjointSet(int size) {
 11	        validateSize(size);
 12	        parent = new int[size];
 13	        componentSize = new int[size];
 14	        componentCount = size;
 15	        initializeSingletonSets();
 16	    }
 17	
 18	    @Override
 19	    public int find(int element) {
 20	        validateIndex(element);
 21	        return findRoot(element);
 22	    }
 23	
 24	    @Override
 25	    public boolean union(int first, int second) {
 26	        int firstRoot = find(first);
 27	        int secondRoot = find(second);
 28	        if (firstRoot == secondRoot) {
 29	            return false;
 30	        }
 31	
 32	        mergeDistinctRoots(largerRoot(firstRoot, secondRoot), smallerRoot(firstRoot, secondRoot));
 33	        componentCount--;
 34	        return true;
 35	    }
 36	
 37	    @Override
 38	    public boolean connected(int first, int second) {
 39	        return find(first) == find(second);
 40	    }
 41	
 42	    @Override
 43	    public int componentSize(int element) {
 44	        return componentSize[find(element)];
 45	    }
 46	
 47	    @Override
 48	    public int components() {
 49	        return componentCount;
 50	    }
 51	
 52	    @Override
 53	    public int size() {
 54	        return parent.length;
 55	    }
 56	
 57	    private void initializeSingletonSets() {
 58	        for (int i = 0; i < parent.length; i++) {
 59	            parent[i] = i;
 60	            componentSize[i] = 1;
 61	        }
 62	    }
 63	
 64	    private int findRoot(int element) {
 65	        int root = rootOf(element);
 66	        compressPathToRoot(element, root);
 67	        return root;
 68	    }
 69	
 70	    private int rootOf(int element) {
 71	        int root = element;
 72	        while (parent[root] != root) {
 73	            root = parent[root];
 74	        }
 75	        return root;
 76	    }
 77	
 78	    private void compressPathToRoot(int element, int root) {
 79	        int current = element;
 80	        while (current != root) {
 81	            int next = parent[current];
 82	            parent[current] = root;
 83	            current = next;
 84	        }
 85	    }
 86	
 87	    private int largerRoot(int firstRoot, int secondRoot) {
 88	        if (componentSize[firstRoot] >= componentSize[secondRoot]) {
 89	            return firstRoot;
 90	        }
 91	        return secondRoot;
 92	    }
 93	
 94	    private int smallerRoot(int firstRoot, int secondRoot) {
 95	        if (componentSize[firstRoot] < componentSize[secondRoot]) {
 96	            return firstRoot;
 97	        }
 98	        return secondRoot;
 99	    }
100	
101	    private void mergeDistinctRoots(int parentRoot, int childRoot) {
102	        attachRoot(childRoot, parentRoot);
103	    }
104	
105	    private void attachRoot(int childRoot, int parentRoot) {
106	        parent[childRoot] = parentRoot;
107	        componentSize[parentRoot] += componentSize[childRoot];
108	    }
109	
110	    private static void validateSize(int size) {
111	        if (size < 0) {
112	            throw new IllegalArgumentException(NEGATIVE_SIZE_MESSAGE);
113	        }
114	    }
115	
116	    private void validateIndex(int element) {
117	        if (element < 0 || element >= parent.length) {
118	            throw new IndexOutOfBoundsException(outOfBoundsMessage(element));
119	        }
120	    }
121	
122	    private String outOfBoundsMessage(int element) {
123	        return "index " + element + " is out of bounds for size " + parent.length;
124	    }
125	}

